from pathlib import Path
import json,gzip,hashlib,datetime
out=Path(__file__).resolve().parents[1];b=json.load(gzip.open(out/'before.json.gz'));scope=json.load(open(out/'scope.json'));assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in b['hashes'].items());assert json.load(gzip.open(out/'before-batch.json.gz'))['sources_unchanged'];assert json.load(gzip.open(out/'before-compat.json.gz'))['sources_unchanged']
nucleus=Path('00_nucleo/prompts/_nuclei/selectors/format-native-identity.toml');assert not nucleus.exists();nucleus.write_text('''tekt = 1
kind = "nucleus"
id = "format-native-element-identity"
title = "Identidade interna dos formatos nativos"

[[claims]]
id = "typed-witness"
level = "must"
statement = "Os cinco formatos svg/png/pdf/html/bundle preservam uma testemunha nominal privada, transportada pela Func efetiva e seus clones. O callback compartilhado, nome, namespace e igualdade Rust não autenticam essa identidade; reconstruir uma Native comum pelo mesmo ponteiro não copia a testemunha."

[[claims]]
id = "native-projections"
level = "must"
statement = "A Func de formato conserva os campos do NativeFunc, ABI estática de quatro argumentos, ponteiro retornado por native_fn_addr, nome, namespace, span diagnóstico, repr, clone e despacho. Eq/Hash conservam a compatibilidade anterior com Native de mesmo nome; isso não concede capacidade de elemento à Native comum. With conserva namespace/nome mas não é elemento bare. Nenhuma chamada de metadados executa callback."

[[claims]]
id = "closed-construction"
level = "must-not"
statement = "Identificar formatos não adiciona binding, muda gate/default, constrói formato manualmente, duplica factory ou cria wrapper de chamada. As factories existentes anexam identidade interna ao NativeFunc original e mantêm namespaces/membros efetivos e fases."

[[claims]]
id = "observation-witness"
level = "must"
statement = "A relação observacional de duas Func de formato compara testemunha nominal, callback, nome e namespace sem execução. Format e Native comum são representações observacionalmente diferentes, mesmo quando Eq público por nome permanece true, pois só a primeira transporta capacidade de seleção."
''');pin=hashlib.sha256(nucleus.read_bytes()+b'\0TEKT-NUCLEUS-DEPS-V1\0').hexdigest();entry='- '+str(nucleus)+' sha256:'+pin
measure='''\n\n## Formatos como funções de elemento — 2026-10-17\n\n### Medição anterior à decisão\n\nHEAD `06848cdcb5450f2c555626bf116bc7acd82bd82b`, working tree não\ncommitado. `00_nucleo/diagnosticos/native-format-catalogue-2026-10-17/`\nconserva before.json.gz com UTC, status, diff HEAD --stat e hashes exatos;\nbaseline-reuse.json prova igualdade de fontes/configuração/binário com a\nmatriz final anterior de 3956 casos em oito perfis. before-batch.json.gz\nmede 144 casos detalhados; before-compat.json.gz mede 456 controles de\nnomes, aliases e namespace. Cada sonda conserva argv, binários e saídas.\nO pin é `9f2b6e8715237cb086899a42873660fe744622e8`, executável SHA-256\n`7fa91e57df43593beef70967898d776d69c8f593b1f324ccb552290821c171ea`.\n\nAs quinze rotas restantes são rejeitadas por where/kind no Tekt e aceitas\nno pin. format.rs:17–27/96–146 compartilha native_format entre os cinco\nformatos, logo só ponteiro não distingue schemas. pinned-schema.json.gz\nconserva nove declarações upstream com blobs/hash/linhas e atributos elem.\nFuncRepr é pub(crate) em entities/func.md:21 e entities/func.rs:24; a nota\nanterior de que o L0 o mostrava público foi refutada em retificacao-func-repr.md.\npublic-contract-before.json fixa assinaturas, reexports e structs públicos\nantes da mudança; a classificação é representação interna e paridade, não\nnovo contrato público ou inferência de intenção por render.\n\n### Responsabilidade exclusiva\n\n'''
bodies={
'01_core/src/entities/func.rs':'''Adicionar `pub(crate) enum FormatElementKind { Svg, Png, Pdf, Html, Bundle }`\nfechado e Copy/Eq, e `FuncRepr::Format(FormatElementKind, NativeFunc)` à enum\nprivada. Func, NativeFunc, NativeFuncWithEngine, ElementFunc, ClosureRepr e\nClosureParam conservam literalmente campos e contratos externos atuais.\nApenas o constructor interno `pub(crate) fn native_format(kind: FormatElementKind,\nnative: NativeFunc) -> Self` inicializa a nova variante com span detached.\nNão criar nova interface pública, alias público de ABI, closure de wrapper,\nside table ou alocação compartilhada global.\n\nNome/namespace/native_fn_addr tratam Format como Native de quatro argumentos:\nretornam os mesmos dados do payload original. element_name continua None para\nambos, reservado ao construtor dinâmico Element. set_name continua só Closure.\nClone continua Arc O(1); With conserva nome/namespace/span e native_fn_addr None.\nEq público agrupa Native e Format em ambos os eixos e compara nomes como antes;\nHash usa o mesmo prefixo 0/nome. Engine mantém prefixo1 e variantes restantes\nprefixo2/Arc; span e kind não entram no Eq/Hash público.\n\nA tabela de reconhecimento, em seu owner, usa a testemunha para os formatos.\nA obrigação anterior de native_fn_addr não mudar None/ponteiro é preservada\npara todos os valores existentes: factories antes Native e depois Format\ncontinuam Some do mesmo ponteiro; os outros seis tipos mantêm os casos antigos.\nTestes de layout imprimem sizeof Func/FuncRepr/NativeFunc/NativeFuncWithEngine\nno RED e no GREEN para medir o custo, sem fazer layout Rust virar paridade.\n''',
'01_core/src/compiler/eval/call_dispatch/apply.rs':'''Aplicar Format pelo mesmo braço estático de Native, usando exatamente o\nNativeFunc.call, ctx, args, World e current_file existentes. Não introduzir\nchamada recursiva/wrapper, nova fase ou nova instalação/restauração de contexto.\nA identificação de span por native_fn_addr continua com o mesmo ponteiro.\n''',
'01_core/src/compiler/eval/bindings/field_access/identity.rs':'''native_public_name inclui o payload Format junto de Native, inclusive ao\ndescascar With. is_user_defined_closure nomeia Format como false. O braço\nNative de is_format_pdf_function também aceita Format e preserva exatamente\na validação atual de nome/namespace, gates e aliases; não usar essa função\ncomo autenticação da capacidade de elemento. Não mudar políticas dos módulos\nstd/format, avisos de símbolos ou diagnósticos a11y.\n''',
'01_core/src/compiler/eval/observation/value.rs':'''Comparar Format somente com Format pelo kind e pelos campos NativeFunc\ncall/name/namespace, sem executar. Kind é comparado por Eq privado; callback\npor fn_addr_eq, nome e namespace pela relação já existente. Nomear Format\nno eixo exaustivo de pares diferentes. Native/Format cruzados são Different,\nmesmo se Eq público for true. Isso observa a capacidade causal de elemento\ne não substitui a igualdade da linguagem por mecânica. Manter todos os\noutros braços de Value/Func/Module e suas prioridades.\n''',
'01_core/src/compiler/stdlib/format.rs':'''Construir cada uma das cinco raízes com Func::native_format e payload\nNativeFunc original: nomes/callback native_format/namespaces permanecem;\nanexar Kind Svg/Png/Pdf/Html/Bundle correspondente. Não tocar o corpo do\ncallback, defaults, ordem de composição, clones de membros, assertions de\ncomposição ou assinaturas das factories. Não criar wrapper. O scope bundle\nconserva asset efetivo clonado.\n''',
'01_core/src/compiler/stdlib/pdf.rs':'''Somente a factory da raiz global pdf passa a produzir Format(Pdf,\nNativeFunc original), com o mesmo native_pdf_root e mesmo Scope. Membros\nattach/artifact e trio a11y permanecem Native, com seus corpos, namespaces,\ngates e ponteiros intactos. A projeção format.pdf continua recebendo e\nclonando esses valores efetivos. Nenhum attachment é lido para metadados.\n''',
'01_core/src/compiler/stdlib/html/namespace.rs':'''Somente a raiz global html passa a Format(Html, NativeFunc original),\ncom mesmo native_html_root e namespace. elem/frame/tags tipadas permanecem\nNative; nomes, callbacks, ordem, feature/target e valores não mudam.\nA projeção format.html continua clonando os membros reais, sem reimplementá-los.\n''',
'01_core/src/compiler/stdlib/html/frame.rs':'''A única mudança deste consumer é native_html_frame de pub(super) para\npub(in crate::compiler), viabilizando ponteiro de metadados por reexport\ndireto. Assinatura, corpo, ordem de validação, parâmetros e resultado são\npreservados. A nativa não vira API externa nem uma nova variante de Func.\n''',
'01_core/src/compiler/stdlib/html.rs':'''Reexportar somente native_html_frame de frame com pub(in crate::compiler),\nantes do módulo inline de testes. Não mover constructor, alterar reexports\npúblicos, tabelas de atributos/tags ou escrever wrapper de chamada.\n''',
'01_core/src/compiler/stdlib/mod.rs':'''Disponibilizar reexports diretos pub(in crate::compiler) de\nhtml::native_html_frame e pdf::{native_pdf_attach,native_pdf_artifact},\nantes do módulo de testes. native_html_elem já é público e não é duplicado.\nPreservar todos os exports externos, factories, registry e helpers.\n'''}
rows='\n'.join('| `'+c['expression']+'` | '+', '.join('`'+f+'`' for f in c['fields'])+' | '+str(c['locatable']).lower()+' |' for c in json.load(open(out/'batch-schema.json'))['cases'])
bodies['01_core/src/compiler/eval/bindings/value_methods/element_where.rs']='''Reconhecer FuncRepr::Format pela testemunha exaustiva Svg/Png/Pdf/Html/Bundle,\ncom nome canônico e schemas da tabela. Não descrever formato pelo mesmo\nponteiro compartilhado, nome ou namespace. Não executar callback. Para os\nquatro elementos reais restantes, usar os callbacks existentes por\nfn_addr_eq: native_pdf_attach, native_pdf_artifact, native_html_elem e\nnative_html_frame. Não aceitar Native não marcada que reutilize callback\nou nome de formato; clone/alias da Func efetiva conserva a marca.\n\n| Rota | Campos selecionáveis, na ordem do pin | Locatable |\n|---|---|---|\n'''+rows+'''\n\nNomes públicos são os últimos segmentos da rota (elem/frame/attach/artifact\nincluídos). HtmlElem exclui css/parent/role internal; label é o filtro comum.\nSomente attach é locatable entre essas nove identidades. Esta capacidade não\nmaterializa counter, indexação ou layout. With continua não-elemento bare e\ncontinua rejeitado por where/kind, sem descascar a aplicação parcial.\nPreservar toda a tabela anterior e os caminhos page/op/raw.line.\n'''
accept='''\n### Aceitação e fronteiras\n\nConsumir as invariantes compartilhadas do Núcleo Tekt pinado\n`00_nucleo/prompts/_nuclei/selectors/format-native-identity.toml`. As novas\nalternativas Native/Format são agrupáveis porque usam o mesmo payload/ABI\npara projeção e execução; cada uma deve ser exercitada nos testes de nome,\nnamespace, ponteiro, Eq/Hash, clone/With e despacho. V19 novo nessas uniões\ndeve ser inventariado e ligado aos testes; não adicionar suppressions.\nA nova variante deve ser explicitamente nomeada nos matches fechados.\n\nFluxo contínuo ADR-0127: nenhuma definição, assinatura, campo ou trait\nexterno novo, compatibilidade, default ou fase muda. Antes do código, RED\nfuncional dos quinze casos por factories atuais e controle de observação\nreal contra Native não marcada. GREEN exige corpus completo, 144 casos de\ncampos/chamadas e 456 controles de compatibilidade preservados fora de\nwhere/kind. Comparar public-contract-before/after e sizeof antes/depois.\n\nL0 antes do código; ownership/V26 antes de resselo restrito aos onze pares.\nBuild, suíte workspace, Clippy/Rustdoc estritos, fmt, V1/V5/V15/V26, reverse\ne diferencial global sem novo erro/aviso. Comandos pesados sequenciais sob\nMemoryMax12GiB/High10GiB/swap0/jobs1. Rastrear notas V19 legítimas com cobertura.\n\nEsta etapa fecha admissão where/kind, não todas as operações de seleção,\nshow/query, síntese, morfologia dos carriers ou counter. As frentes FG1, RM1,\nSY1, RG1 e V16 anteriores preservam seus escopos/gates; não aplicar candidatos\nantigos por cópia nem publicar.\n'''
for source,body in bodies.items():
 p=Path(scope['owners'][source]);s=p.read_text()
 if 'Núcleos Tekt:\n' in s:
  start=s.index('Núcleos Tekt:\n')+len('Núcleos Tekt:\n');end=s.index('\n\n',start);s=s[:start]+'\n'.join(sorted(s[start:end].splitlines()+[entry]))+s[end:]
 else:
  start=s.index('\n',s.index('Hash do Código:'))+1;s=s[:start]+'\nNúcleos Tekt:\n'+entry+'\n'+s[start:]
 p.write_text(s+measure+body+accept)
scope['nuclei']=[str(nucleus)];scope['mode']='Internal Format(FormatElementKind,NativeFunc) witness; eleven owners; external interfaces unchanged; ADR-0127 continuous';(out/'scope.json').write_text(json.dumps(scope,indent=2)+'\n');(out/'l0-before-tests.json').write_text(json.dumps(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),owners={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in scope['owners'].values()},nucleus=str(nucleus),effective_sha256=pin,sources_still_baseline=all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==b['hashes'][p] for p in scope['sources'])),indent=2)+'\n');print('Prescribed',len(bodies),'owners; nucleus',pin)
